@ProbabilityTheory.meas_ge_le_variance_div_sq : ∀ {Ω : Type u_1} {mΩ : MeasurableSpace Ω} {μ : MeasureTheory.Measure Ω}
  [MeasureTheory.IsFiniteMeasure μ] {X : Ω → ℝ},
  MeasureTheory.MemLp X 2 μ →
    ∀ {c : ℝ}, 0 < c → μ {ω | c ≤ |X ω - ∫ (x : Ω), X x ∂μ|} ≤ ENNReal.ofReal (ProbabilityTheory.variance X μ / c ^ 2)

@ProbabilityTheory.IndepFun.variance_sum : ∀ {Ω : Type u_1} {mΩ : MeasurableSpace Ω} {μ : MeasureTheory.Measure Ω}
  {ι : Type u_2} {X : ι → Ω → ℝ} {s : Finset ι},
  (∀ i ∈ s, MeasureTheory.MemLp (X i) 2 μ) →
    ((↑s).Pairwise fun i j ↦ ProbabilityTheory.IndepFun (X i) (X j) μ) →
      ProbabilityTheory.variance (∑ i ∈ s, X i) μ = ∑ i ∈ s, ProbabilityTheory.variance (X i) μ

@ProbabilityTheory.variance_sum_pi : ∀ {ι : Type u_1} [inst : Fintype ι] {Ω : ι → Type u_2}
  {mΩ : (i : ι) → MeasurableSpace (Ω i)} {μ : (i : ι) → MeasureTheory.Measure (Ω i)}
  [∀ (i : ι), MeasureTheory.IsProbabilityMeasure (μ i)] {X : (i : ι) → Ω i → ℝ},
  (∀ (i : ι), MeasureTheory.MemLp (X i) 2 (μ i)) →
    ProbabilityTheory.variance (∑ i, fun ω ↦ X i (ω i)) (MeasureTheory.Measure.pi μ) =
      ∑ i, ProbabilityTheory.variance (X i) (μ i)

@ProbabilityTheory.variance_le_sq_of_bounded : ∀ {Ω : Type u_1} {mΩ : MeasurableSpace Ω} {μ : MeasureTheory.Measure Ω}
  [MeasureTheory.IsProbabilityMeasure μ] {a b : ℝ} {X : Ω → ℝ},
  (∀ᵐ (ω : Ω) ∂μ, X ω ∈ Set.Icc a b) → AEMeasurable X μ → ProbabilityTheory.variance X μ ≤ ((b - a) / 2) ^ 2
